var t=`0102-saltibarsciai`;var r=`world-0102`;var n=`LT`;var a=`northern-europe`;var o=4;var s=102;var l={en:`Šaltibarščiai`,ua:`Шалтібарщяй`};var g={en:`A classic dish from Lithuania, featuring beetroot, kefir, cucumber, dill. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Литва. Основні складники: буряк, кефір, огірок, кріп. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Cook the listed ingredients in simmering water for about 35 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 35 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:35,i:[[`beetroot`,420,`g`],[`water`,1e3,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 45 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 45 хвилин.`,t:[`rapid-chilling`],m:45,i:[[`kefir`,900,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`cucumber`,280,`g`],[`dill`,25,`g`],[`green-onion`,60,`g`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,3,`pcs`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:3,i:[[`sour-cream`,110,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:t,id:r,country:`LT`,region:a,servings:4,minutes:102,title:l,text:g,steps:u};export{n as country,d as default,r as id,s as minutes,a as region,o as servings,t as slug,u as steps,g as text,l as title};